/// The glyph of the icon lucide.dev calls `name`, e.g. `"trash-2"`.
pub fn by_name(name: &str) -> Option<&'static str> {
    BY_NAME
        .binary_search_by(|(known, _)| (*known).cmp(name))
        .ok()
        .map(|index| BY_NAME[index].1)
}
